			fill(255, 255, 0);
		} else {
			fill(255, 0, 0);
		}
		ts = min(150, ts + 20.0 / frameRate());  //make target size incerease at the same speed regardless of framerate
		torus(ts, 0.5);   // targetting "circle"
	}
	pop();

}

function mousePressed() {
	pressed = true;
	auto = false;
}

function mouseReleased() {
	impact((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), ts * 2);
	pressed = false;
	ts = 5;
	lastimpact = millis();
}

// draw another crater heightmap on the existing pGraphic
function impact(x, y, ts) {
	let d = ts
	let light = constrain(map(d, 10, 100, 180, 230),180,230);
	let dark = constrain(map(d, 10, 100, 115, 105),105,115);
	//crater lip
	pg.stroke(light, light, light, 64);
	pg.strokeWeight(2);
	let baseColor=color(pg.get(x,y));  // flatten it out based on the target location height
	baseColor.setAlpha(128)
	pg.fill(baseColor); // flatten
	squircle(x, y, d / 2, 5);
	squircle(x, y, d / 2, 5);
	squircle(x, y, d / 2, 10);
	//crater mound
	pg.noStroke();
	pg.fill(light, light, light, 32);
	squircle(x, y, 1.05 * d / 2, 20);
	//crater
	pg.fill(dark, dark, dark, 25);
	for (let i = 0; i < 20; i++) {
		squircle(x + randomGaussian(), y + randomGaussian(), sqrt(i/20)*(d/2), 40);
	}
	//central peak
	if ((d > 50) && (random(1) < 0.3)) {
		pg.fill(light, light, light, 10);
		for (let i = 0.3 * d / 2; i > 0.01 * d; i *= 0.8) {
			squircle(x + randomGaussian(), y + randomGaussian(), i, 80);
		}
	}
}

//squiggly circle
function squircle(x, y, r, distortion) {
	let points = floor(r * 2);
	pg.beginShape();
	for (let i = 0; i < points; i++) {
		pg.vertex(x + r * cos(TWO_PI * i / points) * (1 + random(distortion / 100)), y + r * sin(TWO_PI * i / points) * (1 + random(distortion / 100)));
	}
	pg.endShape(CLOSE)
}



